const text = ($json.text || '').trim();

const checks = {
  hasText: text.length > 100,
  hasEmail: /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i.test(text),
  hasExperience:
    /\b\d+\+?\s*(years?|yrs?)\b/i.test(text),
  hasSkills:
    /(skills|technical skills|technologies|expertise)/i.test(text)
};

const valid = Object.values(checks).filter(Boolean).length >= 3;

return [{
  json: {
    ...$json,
    resumeQuality: valid ? 'VALID' : 'INVALID',
    resumeQualityChecks: checks
  }
}];

