const text = $input.first().json.content.parts[0].text;

// Parse the text string into a JSON object
const parsedData = JSON.parse(text);

return [
  {
    json: parsedData
  }
];

// JD-Based Candidate Scoring
// Scoring:
// Required Skills  = 50
// Experience        = 25
// Preferred Skills  = 15
// Job Fit           = 10
// Total             = 100

const input = $input.first().json;

// --------------------------------------------------
// Helper functions
// --------------------------------------------------

function normalizeSkill(skill) {
  return String(skill || '')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');
}

function parseSkills(value) {
  if (Array.isArray(value)) {
    return value
      .map(normalizeSkill)
      .filter(Boolean);
  }

  if (typeof value === 'string') {
    return value
      .split(',')
      .map(normalizeSkill)
      .filter(Boolean);
  }

  return [];
}

// --------------------------------------------------
// Read JD + Candidate data
// --------------------------------------------------

const requiredSkills = parseSkills(input['Required Skills']);
const preferredSkills = parseSkills(input['Preferred Skills']);

const matchedSkills = parseSkills(input['Matched Skills']);
const missingSkills = parseSkills(input['Missing Skills']);

const requiredExperience = Number(input['Required Experience']) || 0;
const aiExperience = Number(input['AI Experience']) || 0;

const minimumScore = Number(input['Minimum Score']) || 0;

// --------------------------------------------------
// Create lookup sets
// --------------------------------------------------

const matchedSet = new Set(matchedSkills);
const missingSet = new Set(missingSkills);

// --------------------------------------------------
// 1. REQUIRED SKILLS SCORE - 50
// --------------------------------------------------

// Only calculate against skills actually required by the JD.
//
// Example:
// Required Skills = 4
// Matched Required Skills = 3
//
// Score = (3 / 4) * 50 = 37.5

let matchedRequiredCount = 0;

for (const skill of requiredSkills) {
  if (matchedSet.has(skill)) {
    matchedRequiredCount++;
  }
}

const requiredSkillsScore =
  requiredSkills.length > 0
    ? (matchedRequiredCount / requiredSkills.length) * 50
    : 50;

// --------------------------------------------------
// 2. EXPERIENCE SCORE - 25
// --------------------------------------------------

// Candidate gets full 25 points when experience >= requirement.
//
// Example:
// Required = 5 years
// Candidate = 6 years
// Score = 25
//
// If candidate has less experience:
// score = candidate / required * 25

let experienceScore;

if (requiredExperience <= 0) {
  experienceScore = 25;
} else {
  experienceScore = Math.min(
    (aiExperience / requiredExperience) * 25,
    25
  );
}

// --------------------------------------------------
// 3. PREFERRED SKILLS SCORE - 15
// --------------------------------------------------

// Each preferred skill contributes equally.
//
// Example:
// Preferred = GraphQL, Firebase, Jest
// Candidate matches Firebase
//
// Score = (1 / 3) * 15 = 5

let matchedPreferredCount = 0;

for (const skill of preferredSkills) {
  if (matchedSet.has(skill)) {
    matchedPreferredCount++;
  }
}

const preferredSkillsScore =
  preferredSkills.length > 0
    ? (matchedPreferredCount / preferredSkills.length) * 15
    : 15;

// --------------------------------------------------
// 4. JOB FIT SCORE - 10
// --------------------------------------------------

// Job Fit is based on the percentage of required skills
// matched by the candidate.
//
// 100% required skills = 10
// 80% = 8
// 50% = 5
//
// This is intentionally calculated from JD/candidate data,
// not taken from Gemini.

const requiredSkillMatchPercentage =
  requiredSkills.length > 0
    ? matchedRequiredCount / requiredSkills.length
    : 1;

const jobFitScore = requiredSkillMatchPercentage * 10;

// --------------------------------------------------
// 5. FINAL SCORE
// --------------------------------------------------

const finalScore =
  requiredSkillsScore +
  experienceScore +
  preferredSkillsScore +
  jobFitScore;

// Round to 2 decimal places
const roundedRequiredSkillsScore =
  Math.round(requiredSkillsScore * 100) / 100;

const roundedExperienceScore =
  Math.round(experienceScore * 100) / 100;

const roundedPreferredSkillsScore =
  Math.round(preferredSkillsScore * 100) / 100;

const roundedJobFitScore =
  Math.round(jobFitScore * 100) / 100;

const roundedFinalScore =
  Math.round(finalScore * 100) / 100;

// --------------------------------------------------
// 6. SHORTLIST DECISION
// --------------------------------------------------

const shortlisted = roundedFinalScore >= minimumScore;

const status = shortlisted
  ? 'SHORTLISTED_FOR_HR_REVIEW'
  : 'NOT_SHORTLISTED';

// --------------------------------------------------
// OUTPUT
// --------------------------------------------------

return [
  {
    json: {
      'Required Skills Score': roundedRequiredSkillsScore,
      'Experience Score': roundedExperienceScore,
      'Preferred Skills Score': roundedPreferredSkillsScore,
      'Job Fit Score': roundedJobFitScore,
      'Final Score': roundedFinalScore,
      'Minimum Score': minimumScore,
      'Shortlisted': shortlisted,
      'Status': status
    }
  }
];

