const attendees = $json.attendees || [];

const emails = attendees
  .map(attendee => attendee.email)
  .filter(Boolean);

// Exclude the organizer/self account
const recipientEmails = attendees
  .filter(attendee => !attendee.self)
  .map(attendee => attendee.email)
  .filter(Boolean);

const start = DateTime
  .fromISO($json.start.dateTime)
  .setZone($json.start.timeZone);

const end = DateTime
  .fromISO($json.end.dateTime)
  .setZone($json.end.timeZone);

return [{
  json: {
   attendeeEmails: emails.join(','),
      toEmail: recipientEmails.join(','),
    date: start.toFormat('dd-MM-yyyy'),
    startTime: start.toFormat('hh:mm a'),
    endTime: end.toFormat('hh:mm a')
  }
}];
